      source: 'Robbins & Coulter《Management》；Drucker',
      brief: `**管理是透過他人並與他人一起，有效率且有效能地完成事情的過程。** 這個定義有三個關鍵字：

- **透過他人**：管理者不是自己做完，而是讓別人把事情做成。這是管理者與專業工作者最根本的分野。
- **效率（efficiency）**：投入產出比，**把事情做對（doing things right）**，關心的是手段與資源。
- **效果／效能（effectiveness）**：目標達成度，**做對的事情（doing the right things）**，關心的是目的與結果。

Drucker 的名言：**效率是把事情做對，效果是做對的事情**。兩者的關係是：

> 高效率但低效果 → 用最省的方式做了沒用的事（最危險）
> 低效率但高效果 → 達成了目標但浪費資源（還有救）
> **效果優先於效率** — 方向錯了，跑得越快離目標越遠`,
      advanced: `**為什麼效果優先於效率？** 因為效率是可以事後改善的技術問題，效果卻是方向問題。用錯誤的方向高效執行，損失會隨效率提升而放大。Drucker 說得更狠：「沒有什麼比高效率地做一件根本不該做的事更無用。」

**但實務上兩者並非二選一**。優秀的管理同時追求兩者，只是當資源不足必須取捨時，效果優先。這在申論裡是重要的平衡句，只寫「效果比較重要」會被認為思考不夠周延。

**管理的普遍性（universality of management）**：管理存在於所有規模、所有層級、所有領域（營利與非營利）的組織。但**管理的內容會隨層級與組織類型改變**——基層管理者花更多時間在領導與控制，高層管理者花更多時間在規劃與組織。

**管理者 vs 非管理者的分野**：
- **基層管理者**：管理非管理職的作業人員（領班、組長、主任）
- **中階管理者**：管理基層管理者（部門經理、廠長）
- **高階管理者**：負責組織整體決策與策略（總經理、執行長）

**當代對「管理者」定義的鬆動**值得知道：在扁平化與自主團隊的組織中，管理職責被分散到團隊成員身上，「誰是管理者」的界線不再清楚。這也是為什麼現在談管理越來越常用「管理活動」而非「管理者」為單位。`,
      example: `**餐廳的例子**最好懂：一家餐廳把出餐時間從 12 分鐘壓到 8 分鐘（效率提升），但如果顧客真正在意的是餐點口味與用餐氛圍，那出餐再快也救不了生意——這就是高效率低效果。反過來，一家慢工出細活的餐廳雖然翻桌率低（效率差），但客人願意排隊、願意付高價，它達成了「提供值得等待的用餐體驗」這個目標。`,
