      brief: `**科學管理要解決的問題**：19 世紀末的工廠靠經驗法則（rule of thumb）作業，同一件事十個工人十種做法，效率差異極大，而管理者也不知道「一天合理該做多少」。

**Taylor 的四大原則**：
1. **用科學方法取代經驗法則**——用時間與動作研究找出**唯一最佳方法**（one best way）
2. **科學化地選用與訓練工人**——選對人並教會他最佳方法，而非放任自學
3. **與工人真誠合作**，確保工作照科學方法進行
4. **管理者與工人**（幾乎）**均分工作與責任**——**管理者負責規劃，工人負責執行**

**最容易被誤解的一點**：Taylor 主張的不是「壓榨」，而是**心理革命**（mental revolution）——他認為勞資對立源自把餅視為固定，若效率提升則雙方都能多分，因此配套是**差別計件工資**（達標者領高費率）。

**其他古典代表**：Gilbreth 夫婦（動作研究、減少無效動作）、Gantt（甘特圖與獎工制度）。

**核心貢獻**：把管理從「靠經驗」變成「可研究、可訓練、可複製」的對象。`,
      advanced: `**科學管理的四項批判**，申論必須寫到：
1. **人性假設過窄**：把人視為經濟人（只受金錢驅動），忽略社會需求與自我實現——這正是 [[mgt-02-03]] 霍桑研究要推翻的前提，也是 [[mgt-08-01]] 需求層次理論的起點。
2. **工作去技能化**：把工作切得極碎，導致單調、疏離與意義喪失。這連回 [[mgt-05-01]] 工作專業化的效率曲線——過度分工後效率反而下降，因而後來出現工作擴大化與工作豐富化。
3. **忽略工會與集體議價**：Taylor 主張直接與個別工人打交道，實質削弱了集體協商的基礎，這是當時工會強烈反對的原因。
4. **「唯一最佳方法」在複雜工作上不成立**：對可標準化的體力工作有效，對需要判斷、創造與人際互動的知識工作則不適用——這是 [[mgt-02-04]] 權變觀點的前身。

**但不要因為批判就低估它。** 科學管理的核心邏輯至今仍在運作：生產線的節拍設計、速食店的作業標準、物流倉儲的動線規劃、外送平台的路徑演算法，本質上都是時間與動作研究的延伸。**演算法管理**可視為科學管理的數位版本——差別在於現在由系統即時測量與調度，而不再由拿碼表的工程師執行。這也帶回相同的老問題：效率提升與工作自主性、尊嚴之間的張力。

**Taylor 與 Fayol 的分工**要分清楚（考題常混）：Taylor 從**基層作業**往上看，關心的是**工人怎麼把事做好**；Fayol 從**高階管理**往下看，關心的是**管理者該做什麼**（見 [[mgt-02-02]]）。兩人同屬古典學派，但視角完全相反。`,
      example: `**速食店的作業標準**是科學管理最貼近日常的延續：漢堡的組裝順序、薯條的油炸秒數、動線與器具擺放位置都經過測算，目的正是找出「唯一最佳方法」並讓任何新進人員都能快速達到一致的品質與速度。

代價也同樣清楚：工作被切得極碎、可替代性高、員工難以從中獲得成就感，流動率因而偏高。這正說明科學管理的效率邏輯與其人性成本是同一套設計的兩面，不是可以分開取捨的。

**外送平台的派單與路徑最佳化**則是它的數位版本：系統即時計算最短路徑與最適接單順序，本質仍是時間與動作研究，只是測量工具從碼表換成了 GPS 與演算法，且測量是持續、全面且自動的。`,
