          def: '持續與外部環境進行資源、資訊與能量交換的系統。組織屬於開放系統，須自環境取得投入並將產出回饋至環境；封閉系統因無法自環境取得補充，終將因熵增而走向衰亡。',
          tip: '搭配熵的概念一起講：組織如果不與環境互動就會死。這句話能立刻說明為什麼環境掃描是必要而非選配。'
