          def: '團隊發展的五個階段：形成期成員彼此試探、風暴期衝突與角色爭奪浮現、規範期建立共識與凝聚力、執行期專注於任務產出、解散期任務完成後成員轉移。',
          tip: '核心判斷句：風暴期不是失敗而是必經階段。刻意迴避衝突的團隊會卡在形成期，表面和諧卻無法產出。'
