      source: 'Porter《Competitive Strategy》(1980)',
      brief: `五力決定一個**產業**的平均獲利能力（注意：分析單位是產業，不是單一企業）：

1. **現有競爭者的對抗強度**：競爭者數量與均勢、產業成長率、固定成本比重、產品差異度、退出障礙
2. **潛在進入者的威脅**：由**進入障礙**高低決定 — 規模經濟、資本需求、品牌忠誠、通路取得、轉換成本、政府管制、學習曲線
3. **替代品的威脅**：其他產業中能滿足**同一需要**的產品。替代品的價格績效比越好、轉換成本越低，威脅越大
4. **購買者的議價力**：買方集中度高、採購量大、產品標準化、轉換成本低、可向後整合時，議價力強
5. **供應商的議價力**：供應商集中、投入品獨特、無替代品、可向前整合時，議價力強

**五力越強，產業平均獲利越低。** 策略的目的是**在產業中找到能抵禦五力的位置，或主動改變五力的作用方式**。`,
      advanced: `**最常被考的觀念釐正**：

- **五力分析的是產業結構，不是單一公司的競爭力**。同一產業中不同公司的獲利差異，要用資源基礎觀點（VRIO）或策略群組來解釋。
- **替代品 ≠ 競爭者**。競爭者是同產業提供類似產品者；替代品來自**其他產業**但滿足同一需要。視訊會議是商務航空的替代品，不是競爭者。這是最常錯的一題。
- **五力強不代表不能進入**，只代表產業平均獲利低。仍可能有企業因獨特定位而獲利。

**Porter 五力的四項批評**（進階考點）：
1. **忽略互補品**：Brandenburger & Nalebuff 提出「**第六力：互補者（complementors）**」與價值網（value net）概念。遊戲主機與遊戲軟體、電動車與充電樁互為互補，一方成長會帶動另一方。
2. **假設零和**：五力隱含企業與上下游是對立的分餅關係，忽略合作可以把餅做大（賽局理論的合作觀點）。
3. **靜態**：產業結構被視為相對穩定，難以處理數位平台這類快速改變邊界的情境。
4. **產業邊界模糊化**：平台企業同時是通路、供應商與競爭者，五力的角色分類難以套用。

**進入障礙與退出障礙的組合**（Porter 另一個重要洞見）：
- 高進入 × 低退出 = **最好**（報酬穩定且高）
- 高進入 × 高退出 = 報酬高但有風險
- 低進入 × 低退出 = 報酬低但穩定
- 低進入 × 高退出 = **最差**（報酬低且風險高，例如產能過剩的重資產產業）`,
      example: `**台灣的手搖飲產業**是低獲利的教科書案例：進入障礙極低（設備便宜、技術易得、租約短），現有競爭者眾多且產品高度同質，供應商（茶葉、牛奶、包材）多為標準品但原物料議價力反而不弱，購買者轉換成本幾乎為零，替代品（超商咖啡、瓶裝茶）隨手可得。五力全強，因此產業平均獲利低、汰換率高——能持續獲利的品牌，靠的是五力之外的東西（品牌權益、規模採購、展店選址能力）。`,
