          def: '內容理論探討「什麼因素能激勵人」，聚焦於需求本身，如 Maslow 需求層級、ERG、雙因子與三需求理論；過程理論探討「激勵如何發生」，聚焦於認知歷程，如期望理論、公平理論與目標設定理論。',
