      brief: `組織設計要回答六個問題：

1. **工作專業化**：一件事要切多細？（分工程度）
2. **部門化**：切完之後怎麼分組？（功能／產品／地區／程序／顧客別）
3. **指揮鏈**：誰向誰報告？（權威、命令統一）
4. **控制幅度**：一個主管管幾個人？
5. **集權與分權**：決策權放在高層還是下放？
6. **正式化**：工作被規則與程序標準化到什麼程度？

**兩個容易混淆的概念**：

- **命令統一（unity of command）**：一個部屬只能有一個直屬上司。這是 Fayol 的原則，**矩陣式組織刻意違反它**。
- **控制幅度決定組織的高矮**：幅度越**寬** → 層級越**少** → 組織越**扁平**。反之則高聳。

**控制幅度的取捨**：寬幅度省人事成本、決策快、部屬自主性高，但主管無法細膩指導；窄幅度指導密集，但層級多、溝通失真、成本高。

**當代趨勢**：控制幅度變寬、更分權、正式化降低——但這是**趨勢不是通則**，適用與否取決於底下講的權變因素。`,
      advanced: `**工作專業化的雙面性**是常考的辯證：

Adam Smith 的製針工廠說明分工能大幅提升效率（熟練度提高、切換成本降低、易於訓練與替換）。但**過度專業化會產生反效果**——無聊、疲乏、壓力、缺勤與離職率上升，最終使生產力**不升反降**。

這條「效率先升後降」的曲線，正是 1960 年代後**工作擴大化與工作豐富化**（見 [[mgt-08-02]]）興起的原因：組織開始把過度切碎的工作重新組合回去。

**五種部門化方式的取捨**：

| 方式 | 依據 | 優點 | 缺點 |
|---|---|---|---|
| 功能別 | 專業職能 | 規模經濟、專業深化 | 本位主義、跨部門協調難 |
| 產品別 | 產品線 | 責任明確、貼近產品 | 資源與職能重複 |
| 地區別 | 地理區域 | 貼近當地市場 | 資源重複、總部難掌控 |
| 程序別 | 流程階段 | 流程效率高 | 僅適用特定作業 |
| 顧客別 | 客群類型 | 深入理解特定客群 | 資源重複 |

**功能別是最常見的起點**，因為它最省資源；但企業一旦產品線變多或跨足多個市場，功能別的協調成本會急速上升，這時就會轉向事業部式。

**集權 vs 分權的判準**（不是二選一，而是程度）：

適合**分權**的條件：環境變動快、基層掌握關鍵資訊、決策需要速度、部屬能力足夠、組織地理分散、企業文化容許犯錯。
適合**集權**的條件：環境穩定、決策攸關全局、需要一致性（品牌、法遵）、基層能力或經驗不足。

**正式化的隱藏成本**：高正式化帶來一致性與可預測性，但會**壓抑第一線的判斷力**。速食店的標準化作業手冊是高正式化的典型——它確保每一家店品質一致，代價是店員遇到手冊沒寫的狀況時往往不知所措。這也是為什麼服務業會在標準化與授權之間拉扯（連回 [[mkt-01-03]] 服務業 7P 的 Process 與 People）。`,
      example: `**連鎖餐飲的控制幅度**是很具體的例子。

一家有 300 家門市的連鎖品牌，若採**窄控制幅度**（每位區經理管 5 家店），需要 60 位區經理，上面還要區督導、營運協理——層級多、人事成本高，但每家店能被密集輔導，適合**新品牌或制度未成熟**的階段。

若採**寬控制幅度**（每位區經理管 20 家店），只需 15 位區經理，組織扁平、成本低、決策快——但區經理不可能細膩指導每一家店，因此**必須靠高正式化（標準作業手冊）與資訊系統補上**。

這說明六大要素之間**是互相牽動的，不能各自決定**：想要寬控制幅度，就必須提高正式化或提升店長能力，否則管理就會失控。`,
