            '**給操作方法**：所以我會看它**獎勵誰、懲罰誰、誰被升上去**，而不是看官網或標語。',
            '**補一個實際問法**：面試時可以問「最近一個失敗的專案後來怎麼處理」，答案很能反映真實文化。',
            '**收在一句**：制度管的是規定得到的事，文化管的是規定不到的事——而多數行為都發生在後者。'
