      source: 'Stogdill；俄亥俄州立大學與密西根大學研究；Blake & Mouton（管理方格）',
      brief: `領導理論的發展依序是：**特質論 → 行為論 → 權變論 → 當代理論**。

**特質論（1930–40 年代）** 問的是「**領導者天生具備什麼特質**」。找出的特質包括企圖心、正直誠信、自信、智慧、外向性等。大五人格中，**外向性**最能預測誰會成為領導者。

**特質論的致命限制**：它能預測**誰會浮現為領導者（leader emergence）**，卻不太能預測**誰是有效的領導者（leader effectiveness）**。而且它無法解釋為什麼同一個人在不同情境下表現差異巨大。

**行為論（1940–60 年代）** 把問題從「**領導者是誰**」改成「**領導者做什麼**」。這是關鍵的典範轉移——**因為行為可以訓練，特質不能**。

**兩個經典研究**：
- **俄亥俄州立大學**：**定規**（initiating structure，把任務與角色界定清楚）與**關懷**（consideration，重視部屬感受與關係）。兩者是**獨立的兩個維度**，可以同時很高。
- **密西根大學**：**員工導向**與**生產導向**，早期認為兩者是同一連續帶的兩端。

**管理方格（Blake & Mouton）**：以「對人的關心」與「對生產的關心」各 1–9 分構成 9×9 方格，主張 **(9,9) 團隊型**為最佳。`,
      advanced: `**兩個研究的差別要記清楚**（考題最愛考）：俄亥俄的兩維度是**獨立的**（可以同時高），密西根早期則視為**單一連續帶的兩端**（重視員工就必然犧牲生產）。後續研究支持俄亥俄的觀點——這也是管理方格能成立的前提。

**管理方格的五個代表位置**：

| 座標 | 名稱 | 特徵 |
|---|---|---|
| (1,1) | 無為型 | 對人與生產都不關心，只求不出錯 |
| (1,9) | 鄉村俱樂部型 | 只顧氣氛和諧，績效不佳 |
| (9,1) | 任務型 | 只要產出，不管人的感受 |
| (5,5) | 中庸型 | 兩邊都及格，兩邊都不突出 |
| (9,9) | **團隊型** | 對人與生產都高度關心，公認最佳 |

**行為論的根本限制**：它假設存在**一種放諸四海皆準的最佳領導方式**（也就是 9,9）。但實證上並非如此——高定規高關懷雖然平均而言效果較好，卻**無法在所有情境中都最有效**。

具體的反例：
- 面對**經驗豐富的專業工作者**，過高的定規會被視為微觀管理（micromanagement）而引發反感
- 在**緊急危機**中，高關懷可能延誤決策，此時需要的是明確果斷的指令
- 面對**全新且無經驗的部屬**，高關懷但低定規會讓他們無所適從

這些反例直接催生了**權變理論**——真正的問題不是「哪種行為最好」，而是「**在什麼情境下，哪種行為最好**」。

**特質論的現代復甦值得一提**（加分點）：特質論並未真正死亡。當代研究以**大五人格**與**情緒智商（EQ）** 重新檢視，發現特質雖不能單獨決定領導效能，但確實影響領導者是否被選出、以及其行為傾向。較恰當的當代理解是：**特質提供了傾向與潛力，行為決定了實際效果，情境決定了什麼行為有效**——三者是層層疊加而非互相取代的關係。`,
      example: `**同一位主管在兩個團隊表現天差地遠**，是行為論解釋不了、而權變理論才能處理的典型現象。

假設某位主管的風格是高定規、低關懷——他把工作切得非常清楚、進度盯得很緊、但很少過問部屬的感受。

在一個**成員年資淺、任務標準化的團隊**，這種風格效果很好：新人本來就需要明確指示，知道每天該做什麼反而安心，產出穩定。

換到一個**資深專業工作者組成的團隊**，同樣的風格立刻踢到鐵板：資深成員覺得被當成新人管、專業不被信任，開始消極應對甚至離職。

**主管沒有變，行為也沒有變，效果卻完全相反。** 這正是行為論「存在一種最佳領導方式」假設的破口——也是為什麼領導理論必須走向權變。`,
